<script setup>
import {localRead,localChange,saveLocal,taipeiDay,pruneBackedUp} from '~/utils/local-orders.mjs'
import { dayKey, dailyRevenue, itemCount } from '~/utils/dashboard.mjs'
import { requestAppsScript, listAppsScript } from '~/utils/apps-script.mjs'
const route=useRoute(), category=ref('義式咖啡'), cart=ref([]), orders=ref([]), table=ref('1'), kind=ref('內用'), message=ref(''), busy=ref(false), orderNote=ref('')
const accessKey=useState('pos-access-key',()=>''), connected=useState('pos-connected',()=>false)
const online=ref(true), lastBackup=ref('')
let backupTimer
function updateOnline(){online.value=navigator.onLine;if(online.value)backupIfDue()}
function updateVisible(){if(!document.hidden)backupIfDue()}
onMounted(()=>{online.value=navigator.onLine;window.addEventListener('online',updateOnline);window.addEventListener('offline',updateOnline);document.addEventListener('visibilitychange',updateVisible);accessKey.value=localStorage.getItem('mu-pos-access-key')||'';connected.value=!!accessKey.value;backupTimer=setInterval(backupIfDue,60000);backupIfDue()})
onBeforeUnmount(()=>{clearInterval(backupTimer);window.removeEventListener('online',updateOnline);window.removeEventListener('offline',updateOnline);document.removeEventListener('visibilitychange',updateVisible)})
async function backupIfDue(){if(!online.value||!accessKey.value||busy.value)return;const state=await localRead();if(!state.queue.length&&localStorage.getItem('mu-menu-dirty')!=='1')return;const last=Date.parse(state.lastSync||'')||0;if(Date.now()-last>=1800000)await sync()}
const connectDialog=ref(null), keyInput=ref(''), connectError=ref(''), connecting=ref(false)
const pendingCheckout=ref(null)
const saving=ref(false)
const writable=computed(()=>!saving.value&&!pendingCheckout.value)
const cloudOrders=useState('pos-cloud-orders',()=>[])
watch(cloudOrders,v=>{orders.value=v},{immediate:true})


const snackbar=ref('')
let snackbarTimer
function showSnackbar(text){clearTimeout(snackbarTimer);snackbar.value=text;snackbarTimer=setTimeout(()=>{snackbar.value=''},3000)}
onBeforeUnmount(()=>clearTimeout(snackbarTimer))
const groups=reactive([
['義式咖啡','美式咖啡:100,義式特濃咖啡:100,卡布奇諾:120,拿鐵:120,焦糖瑪奇朵:130,榛果拿鐵:130,玫瑰拿鐵:130,愛爾蘭拿鐵:130,摩卡奇諾:130,海鹽拿鐵:130,太妃糖拿鐵:130,維也納:130,摩卡維也納:140,焦糖維也納:140,烤黑糖拿鐵:140,冰淇淋咖啡:150,冰檸檬咖啡:150'],
['賽風咖啡','純品藍山:150,香濃曼特寧:130,香醇曼巴:130,風味巴西:130,干邑摩卡:130,綜合咖啡:130'],
['茶','鮮果煮茶:120,義大利桔茶:120,柚子茶:120,伯爵茶:120,皇家錫蘭紅茶:100,茉香綠茶:100,玫瑰花茶:120,葡萄柚綠茶:120,百香風情:120,蜂蜜紅茶:120,檸檬紅茶:120,洛神花茶:120,梅子綠茶:120'],
['香濃奶茶','英式伯爵奶茶:120,皇家錫蘭奶茶:100,北美榛果奶茶:120,焦糖奶茶:120,可可奶茶:120,抹茶鮮奶茶:150,玫瑰鮮奶茶:150,太妃糖鮮奶茶:150,愛爾蘭鮮奶茶:150,黑糖珍珠奶茶:150,冰淇淋奶茶:150'],
['花草茶','普洱茶:150,桂圓紅棗茶:150,玄米茶:150,烏龍茶:150,南非國寶茶:150,洋甘菊花茶:150,養生茶:150,康福茶:150'],
['冰沙','咖啡冰沙:150,摩卡冰沙:150,巧克力冰沙:150,巧酥冰沙:150,抹茶奶霜:150,芒果冰沙:150,桑椹冰沙:150'],
['其他飲品','鮮榨柳丁汁:140,鮮榨檸檬汁:140,奇異果汁:140,蛋蜜汁:150,鮮奶:100,焦糖牛奶:120,榛果牛奶:120,巧克力牛奶:120,烤黑糖牛奶:120,黑糖珍珠牛奶:150,太妃糖牛奶:120,啤酒:150'],
['鬆餅','奶油鬆餅:150,覆盆莓果醬鬆餅:150,草莓果醬鬆餅:150,巧克力淋醬鬆餅:150,蜂蜜淋醬鬆餅:150,焦糖淋醬鬆餅:150,冰淇淋鬆餅:180'],
['厚片土司','起司奶油厚片:70,特濃花生厚片:60,香酥奶油厚片:60,美味香蒜厚片:60,香甜奶酥厚片:60,可口草莓厚片:60,巧克力厚片:60'],
['主餐','青醬牛肉義大利麵:250,焗烤茄汁牛肉千層麵:250,焗烤奶油海鮮螺旋麵:250,焗烤奶油海鮮飯:250,焗烤培根雞肉螺旋麵:250,焗烤培根雞肉飯:250,威尼斯奶油雞丁義大利麵:230,拿波里香辣雞肉義大利麵:230,西西里肉醬義大利麵:230,野菜南瓜素雞丁義大利麵:230']])
groups.push(['今日蛋糕','提拉米蘇:100,紐奧良起司:100,巧克力慕斯:100,巧克力伯爵:100,金莎巴斯克:100,烤布蕾:100'])
groups.push(['熟客券','熟客券:1000'])
groups.push(['減項','', 'system-discount'])
const menu=reactive(groups.flatMap(([group,items],g)=>(items?items.split(','):[]).map((s,i)=>{const [name,p]=s.split(':');return {id:g+'-'+i,group,name,price:Number(p),active:true}})))
groups.forEach((group,index)=>{group[2] ||= 'legacy-'+index})
const selectedSettingsCategory=ref(groups[0][0])
const visibleSettingsItems=computed(()=>menu.filter(item=>item.group===selectedSettingsCategory.value))
const categoryDialog=ref(null), categoryDraft=ref(''), categoryError=ref(''), editingCategory=ref(null)
const itemDialog=ref(null), itemDraft=ref(null), itemError=ref(''), editingItemId=ref(null)
const itemCategoryPicker=ref(null), itemCategoryOpen=ref(false)
function closeItemCategoryOutside(event){if(itemCategoryOpen.value&&!itemCategoryPicker.value?.contains(event.target))itemCategoryOpen.value=false}
onMounted(()=>document.addEventListener('pointerdown',closeItemCategoryOutside))
onBeforeUnmount(()=>document.removeEventListener('pointerdown',closeItemCategoryOutside))
function chooseItemCategory(name){itemDraft.value.group=name;itemCategoryOpen.value=false}
const adminUnlocked=ref(false), adminPin=ref(''), adminInput=ref(''), adminError=ref('')
const storageUsage=ref('計算中…')
const menuRestoreDialog=ref(null)
async function restoreMenuFromCloud(){try{const result=await requestAppsScript(accessKey.value,{action:'menuGet'});if(!result.data.length)throw Error('雲端尚無菜單備份');const categories=result.data.filter(item=>item.id.startsWith('category:')).map(item=>({name:item.group,id:item.id.slice(9)}));const items=result.data.filter(item=>!item.id.startsWith('category:'));if(!items.length)throw Error('雲端菜單沒有品項');menu.splice(0,menu.length,...items);groups.splice(0,groups.length,...(categories.length?categories.map(category=>[category.name,'',category.id]):[...new Set(items.map(item=>item.group))].map(name=>[name,'',crypto.randomUUID()])));if(!groups.some(group=>group[0]==='減項'))groups.push(['減項','','system-discount']);selectedSettingsCategory.value=groups[0]?.[0]||'';persistCategories();menuRestoreDialog.value.close();showSnackbar('已還原雲端菜單')}catch(error){showSnackbar(error.message)}}
async function inspectStorage(){if(!navigator.storage?.estimate){storageUsage.value='此瀏覽器無法提供用量';return}const {usage,quota}=await navigator.storage.estimate();storageUsage.value=`已用 ${((usage||0)/1048576).toFixed(1)} MB／可用配額 ${((quota||0)/1048576).toFixed(0)} MB`}
onMounted(()=>{try{const saved=JSON.parse(localStorage.getItem('mu-menu')||'null');if(Array.isArray(saved)&&saved.length)menu.splice(0,menu.length,...saved);else localStorage.setItem('mu-menu-dirty','1');let migrated=false;menu.forEach(item=>{if(!item.options){item.options=menuOptions(item);migrated=true}});const categories=JSON.parse(localStorage.getItem('mu-categories')||'null');if(Array.isArray(categories)){if(categories.some(entry=>entry&&typeof entry==='object')){const byName=new Map(groups.map(group=>[group[0],group]));const ordered=categories.filter(entry=>typeof entry?.name==='string').map(entry=>{const group=byName.get(entry.name)||[entry.name,''];group[2]=entry.id||crypto.randomUUID();return group});groups.splice(0,groups.length,...ordered)}else{for(const name of categories)if(typeof name==='string'&&!groups.some(group=>group[0]===name))groups.push([name,'',crypto.randomUUID()]);migrated=true}}else migrated=true;if(!groups.some(group=>group[0]==='減項')){groups.push(['減項','', 'system-discount']);migrated=true}if(migrated){localStorage.setItem('mu-menu',JSON.stringify(menu));persistCategories()}selectedSettingsCategory.value=groups[0]?.[0]||''}catch(error){showSnackbar('讀取菜單失敗：'+error.message)}watch(menu,()=>{try{localStorage.setItem('mu-menu',JSON.stringify(menu));localStorage.setItem('mu-menu-dirty','1');inspectStorage().catch(()=>{})}catch{showSnackbar('菜單儲存空間不足，修改未保存')}},{deep:true})})
async function hashPin(pin){const bytes=new TextEncoder().encode('mu-pos-admin:'+pin);const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function unlockAdmin(){if(!/^\d{6,}$/.test(adminInput.value)){adminError.value='請輸入至少六位數 PIN';return}const stored=localStorage.getItem('mu-admin-pin');const hash=await hashPin(adminInput.value);if(stored&&stored!==hash){adminError.value='PIN 不正確';return}if(!stored)localStorage.setItem('mu-admin-pin',hash);adminUnlocked.value=true;adminInput.value='';adminError.value=''}
function persistCategories(){localStorage.setItem('mu-categories',JSON.stringify(groups.map(group=>({name:group[0],id:group[2]}))));localStorage.setItem('mu-menu-dirty','1');inspectStorage().catch(()=>{})}
function openCategoryDialog(group=null){editingCategory.value=group;categoryDraft.value=group?.[0]||'';categoryError.value='';categoryDialog.value.showModal()}
function saveCategory(){const name=categoryDraft.value.trim();if(editingCategory.value?.[0]==='減項'&&name!=='減項'){categoryError.value='減項分類名稱不可修改';return}if(!name){categoryError.value='請輸入分類名稱';return}if(groups.some(group=>group[0]===name&&group!==editingCategory.value)){categoryError.value='分類名稱已存在';return}if(editingCategory.value){const old=editingCategory.value[0];editingCategory.value[0]=name;menu.forEach(item=>{if(item.group===old)item.group=name});selectedSettingsCategory.value=name}else{groups.push([name,'',crypto.randomUUID()]);selectedSettingsCategory.value=name}persistCategories();categoryDialog.value.close()}
function removeCategory(group){if(group[0]==='減項'){categoryError.value='減項分類不可移除';return}if(menu.some(item=>item.group===group[0])){categoryError.value='請先移動此分類的品項';return}const index=groups.indexOf(group);groups.splice(index,1);selectedSettingsCategory.value=groups[Math.max(0,index-1)]?.[0]||'';persistCategories();categoryDialog.value.close()}
function menuOptions(item){if(item.group==='減項')return [];if(item.options)return item.options;const price=item.price;const cold={value:'冰杯',price},hot={value:item.group==='茶'||item.group==='香濃奶茶'?'熱壺':'熱杯',price:item.group==='茶'||item.group==='香濃奶茶'?150:price};if(item.group==='茶'||item.group==='香濃奶茶')return item.name==='冰淇淋奶茶'?[cold]:[cold,hot];if(item.group==='義式咖啡')return item.name.startsWith('冰')?[cold]:[cold,hot];if(item.group==='花草茶')return [{value:'熱壺',price}];if(item.group==='冰沙')return [cold];return []}
function openItemDialog(item=null){editingItemId.value=item?.id||null;itemDraft.value=item?JSON.parse(JSON.stringify(item)):{id:crypto.randomUUID(),group:selectedSettingsCategory.value,name:'',price:0,active:true,options:[]};itemDraft.value.options=JSON.parse(JSON.stringify(menuOptions(itemDraft.value)));itemError.value='';itemCategoryOpen.value=false;itemDialog.value.showModal()}
function setItemMode(mode){const item=itemDraft.value;if(!item||item.group==='減項')return;const current=item.options||[];const cold=current.find(option=>option.value.startsWith('冰'))||{value:'冰杯',price:item.price||0};const hot=current.find(option=>option.value.startsWith('熱'))||{value:['茶','香濃奶茶','花草茶'].includes(item.group)?'熱壺':'熱杯',price:item.price||0};item.options=mode==='無冷熱'?[]:mode==='僅冰'?[cold]:mode==='僅熱'?[hot]:[cold,hot]}
function itemMode(item){const options=item?.options||[];const cold=options.some(option=>option.value.startsWith('冰')),hot=options.some(option=>option.value.startsWith('熱'));return cold&&hot?'冰熱都有':cold?'僅冰':hot?'僅熱':'無冷熱'}
function saveItemDraft(){const item=itemDraft.value;if(!item?.name.trim()){itemError.value='請輸入品項名稱';return}if(!groups.some(group=>group[0]===item.group)){itemError.value='請選擇分類';return}if(item.group==='減項')item.options=[];const validPrice=price=>Number.isSafeInteger(price)&&price>=-10000000&&price<=10000000&&(item.group==='減項'?price<=0:price>=0);if(!validPrice(item.price)||item.options.some(option=>!validPrice(option.price))){itemError.value=item.group==='減項'?'減項價格須為 0 或負整數':'價格須為非負整數';return}item.price=item.options[0]?.price??item.price;const index=menu.findIndex(row=>row.id===editingItemId.value);if(index>=0)menu.splice(index,1,item);else menu.push(item);selectedSettingsCategory.value=item.group;itemDialog.value.close()}
function moveItem(item,delta){const categoryItems=visibleSettingsItems.value;const target=categoryItems[categoryItems.indexOf(item)+delta];if(!target)return;const a=menu.indexOf(item),b=menu.indexOf(target);[menu[a],menu[b]]=[menu[b],menu[a]]}
function moveCategory(group,delta){const index=groups.indexOf(group),next=index+delta;if(next<0||next>=groups.length)return;[groups[index],groups[next]]=[groups[next],groups[index]];persistCategories()}
groups.push(...groups.splice(groups.findIndex(([name])=>name==='主餐'),1))
const menuScroll=ref(null)
let menuAnimation=0
function stopMenuAnimation(){cancelAnimationFrame(menuAnimation)}
onBeforeUnmount(stopMenuAnimation)
function jump(name){
stopMenuAnimation()
category.value=name
const root=menuScroll.value
const el=root?.querySelector('[data-group="'+name+'"]')
if(!el)return
const start=root.scrollTop
const target=Math.max(0,Math.min(el.offsetTop-root.offsetTop,root.scrollHeight-root.clientHeight))
if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){root.scrollTop=target;return}
const began=performance.now()
function frame(now){const t=Math.min(1,(now-began)/160);root.scrollTop=start+(target-start)*(1-(1-t)**3);if(t<1)menuAnimation=requestAnimationFrame(frame)}
menuAnimation=requestAnimationFrame(frame)
}

function track(){const root=menuScroll.value;if(!root)return;const sections=[...root.querySelectorAll('[data-group]')];const top=root.getBoundingClientRect().top;const active=sections.filter(el=>el.getBoundingClientRect().top<=top+40).at(-1)||sections[0];if(active)category.value=active.dataset.group}

const total=computed(()=>cart.value.reduce((a,i)=>a+i.price*i.qty,0)), net=computed(()=>orders.value.reduce((a,o)=>a+o.total,0))
const money=n=>n.toLocaleString()+' 元'
onMounted(()=>{for(const [k,r] of Object.entries({cart,orderNote,pendingCheckout})){try{const v=localStorage.getItem('mu-'+k);if(v)r.value=JSON.parse(v)}catch{}watch(r,v=>localStorage.setItem('mu-'+k,JSON.stringify(v)),{deep:true})}})
function variants(p){const base=menu.find(item=>item.id===p.id)||p;return menuOptions(base).map(option=>({label:option.value==='熱壺'?'熱（壺）':option.value==='冰杯'&&(base.group==='茶'||base.group==='香濃奶茶')?'冰（杯）':option.value.startsWith('冰')?'冰':'熱',value:option.value,price:option.price}))}
const tableDialog=ref(null)
const tableChoices=['外帶','A1','A2','B1','B2','B3','B4',...Array.from({length:10},(_,i)=>String(i+1))]
function chooseTable(value){kind.value=value==='外帶'?'外帶':'內用';table.value=value==='外帶'?'':value;tableDialog.value.close()}
function normalizeItem(i){i.variant??='';i.sweetness??='正常';i.ice??=i.variant.startsWith('冰')?'正常':'';i.heat??=i.variant.startsWith('熱')?'熱':'';return i}
function migrateNotes(items,note=''){const legacy=items.filter(i=>i.note).map(i=>i.name+'：'+i.note);items.forEach(i=>{delete i.note});return [note,...legacy].filter(Boolean).join('；')}
onMounted(()=>{cart.value.forEach(normalizeItem);orderNote.value=migrateNotes(cart.value,orderNote.value)})
const levels=['正常','半','少','微','無']
function add(p,option){
if(!writable.value||(variants(p).length&&!option))return
cart.value.push({...p,lineId:crypto.randomUUID(),variant:option?.value||'',price:option?.price??p.price,qty:1,sweetness:'正常',ice:option?.value.startsWith('冰')?'正常':'',heat:option?.value.startsWith('熱')?'熱':''})
}
const priceDialog=ref(null), priceTarget=ref(null), priceValue=ref(''), priceError=ref('')
function editPrice(i){
if(!writable.value)return
priceTarget.value=i;priceValue.value=String(i.price);priceError.value=''
priceDialog.value.showModal()
}
function savePrice(){
const value=priceValue.value.trim(),discount=priceTarget.value?.group==='減項';if(!/^-?\d+$/.test(value)||!Number.isSafeInteger(Number(value))||Math.abs(Number(value))>10000000||(discount?Number(value)>0:Number(value)<0)){priceError.value=discount?'減項單價須為 0 或負整數':'單價須為非負整數';return}
if(priceTarget.value&&cart.value.includes(priceTarget.value)){priceTarget.value.price=Number(priceValue.value);priceTarget.value.priceOverridden=true}
priceDialog.value.close()
}
function toggleTemperature(i){
if(!writable.value)return
const options=variants(i)
if(options.length<2)return
const next=options.find(o=>o.value!==i.variant)
if(!next)return
i.variant=next.value;if(!i.priceOverridden)i.price=next.price
i.ice=next.value.startsWith('冰')?'正常':''
i.heat=next.value.startsWith('熱')?'熱':''
}
function menuPrice(p){const prices=[...new Set(variants(p).map(o=>o.price))];return prices.length>1?prices.join('／')+' 元':money(p.price)}
function isDrink(i){return ['義式咖啡','賽風咖啡','茶','香濃奶茶','花草茶','冰沙','其他飲品'].includes(i.group)&&i.name!=='啤酒'}

const selectedMonth=useState('pos-selected-month',()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit'}).format(new Date()))
const selectedDay=ref(taipeiDay(new Date()))
function shiftDay(delta){const d=new Date(selectedDay.value+'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()+delta);selectedDay.value=taipeiDay(d);selectedMonth.value=selectedDay.value.slice(0,7)}
function shiftMonth(delta){const [year,month]=selectedMonth.value.split('-').map(Number);const d=new Date(Date.UTC(year,month-1+delta,1));selectedMonth.value=d.toISOString().slice(0,7)}
const dailyTotal=computed(()=>orders.value.filter(o=>dayKey(o.date)===selectedDay.value).reduce((n,o)=>n+o.total,0))
watch(selectedMonth,async()=>{if(selectedDay.value&&!selectedDay.value.startsWith(selectedMonth.value))selectedDay.value=selectedMonth.value+'-01';await refreshLocal();const current=taipeiDay(new Date()).slice(0,7);if(selectedMonth.value<current&&connected.value&&online.value&&orders.value.length===0)await downloadMonth()})
const expandedOrders=ref(new Set()), orderFilter=ref('全部')
const sortedOrders=computed(()=>[...orders.value].sort((a,b)=>new Date(b.date)-new Date(a.date)))
const filteredOrders=computed(()=>sortedOrders.value.filter(o=>!selectedDay.value||dayKey(o.date)===selectedDay.value))
function toggleOrder(id){const next=new Set(expandedOrders.value);next.has(id)?next.delete(id):next.add(id);expandedOrders.value=next}
const days=computed(()=>dailyRevenue(orders.value,selectedMonth.value))
const maxRevenue=computed(()=>Math.max(1,...days.value.map(d=>d.total)))
const chartPoints=computed(()=>days.value.map((day,index)=>({date:day.date,total:day.total,x:40+index*720/Math.max(1,days.value.length-1),y:215-day.total/maxRevenue.value*175})))
const chartPath=computed(()=>chartPoints.value.map((point,index)=>(index?'L':'M')+point.x.toFixed(1)+' '+point.y.toFixed(1)).join(' '))
const average=computed(()=>orders.value.length?Math.round(net.value/orders.value.length):0)
const dineIn=computed(()=>orders.value.filter(o=>o.kind==='內用').length)
const popular=computed(()=>{const map=new Map();orders.value.forEach(o=>o.items.forEach(i=>{const p=map.get(i.id)||{name:i.name,qty:0,total:0};p.qty+=i.qty;p.total+=i.price*i.qty;map.set(i.id,p)}));return [...map.values()].sort((a,b)=>b.total-a.total).slice(0,5)})
const timeLabel=date=>new Date(date).toLocaleTimeString('zh-TW',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false})
const dateLabel=date=>dayKey(date).slice(5).replace('-',' / ')
const orderLabel=o=>o.orderNo?'#'+o.orderNo.split('-').at(-1):'舊單'
const pendingIds=ref(new Set())
const pendingCount=ref(0), lastSync=ref(''), monthComplete=ref(false)
async function refreshLocal(){const state=await localRead();cloudOrders.value=state.orders.filter(o=>o.month===selectedMonth.value);pendingCount.value=state.queue.length;pendingIds.value=new Set(state.queue.map(op=>op.order.id));lastSync.value=state.lastSync||'';monthComplete.value=state.cachedMonth===selectedMonth.value;inspectStorage().catch(()=>{storageUsage.value='暫時無法取得用量'})}
onMounted(()=>refreshLocal().catch(e=>showSnackbar('本機資料讀取失敗：'+e.message)))
async function loadCloud(key,force=false){
const month=selectedMonth.value
const local=await localRead()
if(!force&&local.cachedMonth===month&&Number.isInteger(local.syncCursor)){
let cursor=local.syncCursor;const map=new Map(local.orders.filter(o=>o.month===month).map(o=>[o.id,o]))
while(true){let r;try{r=await requestAppsScript(key,{action:'changes',month,since:cursor})}catch(e){if(e.code==='STALE_CURSOR')return loadCloud(key,true);throw e}r.deleted.forEach(id=>map.delete(id));r.data.forEach(o=>map.set(o.id,o));cursor=r.nextCursor;if(cursor>=r.syncCursor)return {orders:[...map.values()],cursor,month}}
}
const orders=[];let offset=0,revision,cursor
while(true){const r=await requestAppsScript(key,{action:'list',month,offset,revision});orders.push(...r.data);revision=r.revision;cursor=r.syncCursor;if(r.nextOffset==null)return {orders,cursor,month};offset=r.nextOffset}
}
function applyCloud(){refreshLocal()}
async function resolveLegacy(key){
if(!pendingCheckout.value)return
const pending=JSON.parse(JSON.stringify(pendingCheckout.value))
try{const result=await requestAppsScript(key,{action:'get',id:pending.id});await localChange(state=>{if(!state.orders.some(o=>o.id===pending.id))state.orders.push(result.data);const day=taipeiDay(result.data.date);state.counters[day]=Math.max(state.counters[day]||0,Number(result.data.orderNo?.split('-').pop())||0)})}catch(e){if(e.code!=='NOT_FOUND')throw e;await saveLocal(pending)}
pendingCheckout.value=null;localStorage.removeItem('mu-pendingCheckout');cart.value=[];orderNote.value='';await refreshLocal()
}
async function downloadMonth(){if(!connected.value){connectDialog.value.showModal();return}if(busy.value)return;busy.value=true;try{const remote=await loadCloud(accessKey.value);await localChange(state=>{const dirty=new Set(state.queue.map(o=>o.order.id));state.orders=state.orders.filter(o=>o.month!==remote.month||dirty.has(o.id));state.orders.push(...remote.orders.filter(o=>!dirty.has(o.id)));state.cachedMonth=remote.month;state.syncCursor=remote.cursor;remote.orders.forEach(o=>{const day=taipeiDay(o.date);state.counters[day]=Math.max(state.counters[day]||0,Number(o.orderNo?.split('-').pop())||0)})});await refreshLocal();showSnackbar('月份資料已下載')}catch(e){showSnackbar(e.message)}finally{busy.value=false}}
async function connect(){
if(connecting.value)return
connecting.value=true;connectError.value=''
try{const key=keyInput.value.trim();await requestAppsScript(key,{action:'list',month:selectedMonth.value,offset:0});accessKey.value=key;localStorage.setItem('mu-pos-access-key',key);connected.value=true;await resolveLegacy(key);keyInput.value='';connectDialog.value.close();showSnackbar('已連線')}catch(e){connectError.value=e.message}finally{connecting.value=false}
}
function disconnect(){accessKey.value='';localStorage.removeItem('mu-pos-access-key');connected.value=false;keyInput.value='';showSnackbar('已中斷連線')}
async function sync(){if(navigator.locks){await navigator.locks.request('mu-pos-sync',{ifAvailable:true},async lock=>{if(!lock){showSnackbar('另一個分頁正在同步');return}await performSync()})}else await performSync()}
async function sendSyncBatch(batch){for(let attempt=0;;attempt++){try{return await requestAppsScript(accessKey.value,{action:'sync',operations:batch})}catch(e){const retryable=e instanceof TypeError||!e.code||['RATE_LIMITED','BUSY_RETRY','SERVER_ERROR'].includes(e.code);if(!retryable||attempt>=2)throw e;await new Promise(resolve=>setTimeout(resolve,500*2**attempt+Math.random()*250))}}}
async function performSync(){
if(busy.value)return;if(!connected.value){connectDialog.value.showModal();return}
busy.value=true
try{
const snapshot=(await localRead()).queue
let offset=0
while(offset<snapshot.length){
const batch=[]
while(offset<snapshot.length&&batch.length<10){const next=snapshot[offset];if(new TextEncoder().encode(JSON.stringify({action:'sync',operations:[...batch,next],key:accessKey.value})).length>100000){if(!batch.length)throw Error('單筆同步資料過大，請備份並檢查訂單');break}batch.push(next);offset++}
const r=await sendSyncBatch(batch)
for(const result of r.data){if(!result.ok)throw Error(result.error==='ORDER_NUMBER_CONFLICT'?'流水號重複，請重新編號後再同步':result.error);await localChange(state=>{state.queue=state.queue.filter(x=>x.operationId!==result.operationId)})}
if(r.data.length<batch.length)break
}
if(localStorage.getItem('mu-menu-dirty')==='1'){await requestAppsScript(accessKey.value,{action:'menuSave',data:[...groups.map((g,index)=>({id:'category:'+g[2],group:g[0],name:g[0],price:0,active:true})),...JSON.parse(JSON.stringify(menu.map(item=>({...item,options:menuOptions(item)}))))]});localStorage.removeItem('mu-menu-dirty')}
await localChange(state=>{state.lastSync=new Date().toISOString()})
await pruneBackedUp()
await refreshLocal();showSnackbar(pendingCount.value?'部分完成，仍有 '+pendingCount.value+' 筆待同步':'同步完成')
}catch(e){if(e.code==='UNAUTHORIZED'){accessKey.value='';connected.value=false;localStorage.removeItem('mu-pos-access-key')}showSnackbar('同步未完成：'+e.message)}finally{busy.value=false;await refreshLocal()}
}
async function checkout(){if(pendingCheckout.value){connectDialog.value.showModal();return}if(!cart.value.length||saving.value)return;saving.value=true;try{await saveLocal({kind:kind.value,table:table.value,note:orderNote.value,items:JSON.parse(JSON.stringify(cart.value))});cart.value=[];orderNote.value='';pendingCheckout.value=null;await refreshLocal();showSnackbar('已儲存於本機')}catch(e){showSnackbar('儲存失敗，訂單已保留：'+e.message)}finally{saving.value=false}}
const editDialog=ref(null), editOrder=ref(null), editError=ref('')
function openOrder(o){editOrder.value=JSON.parse(JSON.stringify(o));editError.value='';editDialog.value.showModal()}
async function saveOrder(){try{await saveLocal(JSON.parse(JSON.stringify(editOrder.value)));await refreshLocal();editDialog.value.close();showSnackbar('已儲存於本機')}catch(e){editError.value=e.message}}
const deleteDialog=ref(null), deleteTarget=ref(null)
function deleteOrder(o){deleteTarget.value=o;deleteDialog.value.showModal()}
async function confirmDelete(){try{await saveLocal(JSON.parse(JSON.stringify(deleteTarget.value)),true);await refreshLocal();deleteDialog.value.close();showSnackbar('刪除待同步')}catch(e){showSnackbar(e.message)}}
async function refund(o,i){const qty=Number(prompt('退單數量',1));if(!Number.isInteger(qty)||qty<1||qty>i.qty)return;const reason=prompt('退單原因');if(!reason)return;try{const copy=JSON.parse(JSON.stringify(o));copy.items.find(x=>x.lineId===i.lineId).qty-=qty;copy.items=copy.items.filter(x=>x.qty>0);copy.refundReason=reason;copy.refundDate=new Date().toISOString();await saveLocal(copy);await refreshLocal();showSnackbar('退單待同步')}catch(e){showSnackbar(e.message)}}
async function renumberPending(){try{if(!connected.value)throw Error('請先連線');const state=await localRead();const months=[...new Set(state.queue.filter(o=>!o.remove).map(o=>o.order.month))];const remote=(await Promise.all(months.map(month=>requestAppsScript(accessKey.value,{action:'list',month})))).flatMap(r=>r.data);await localChange(state=>{const existing=new Map(remote.map(o=>[o.id,o]));remote.forEach(o=>{const day=taipeiDay(o.date);state.counters[day]=Math.max(state.counters[day]||0,Number(o.orderNo?.split('-').pop())||0)});const assigned=new Map();state.queue.forEach(op=>{if(op.remove)return;let number=assigned.get(op.order.id)||existing.get(op.order.id)?.orderNo;if(!number){const day=taipeiDay(op.order.date);state.counters[day]=(state.counters[day]||0)+1;number=day.replaceAll('-','')+'-'+String(state.counters[day]).padStart(3,'0')}assigned.set(op.order.id,number);op.order.orderNo=number;const order=state.orders.find(o=>o.id===op.order.id);if(order)order.orderNo=number})});await refreshLocal();showSnackbar('待同步單已重新編號，請再點同步')}catch(e){showSnackbar(e.message)}}
async function backupLocal(){try{const state=await localRead();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({format:'mu-pos-backup-v1',state})],{type:'application/json'}));a.download='mu-pos-'+taipeiDay(new Date())+'.json';a.click();URL.revokeObjectURL(a.href)}catch(e){showSnackbar(e.message)}}
async function restoreLocal(event){try{const file=event.target.files[0];if(!file)return;if(file.size>50000000)throw Error('備份檔過大');const backup=JSON.parse(await file.text());const state=backup.state;if(backup.format!=='mu-pos-backup-v1'||!Array.isArray(state?.orders)||!Array.isArray(state?.queue)||state.orders.some(o=>!o.id||!Array.isArray(o.items))||state.queue.some(o=>!o.operationId||!o.order?.id))throw Error('備份格式不符');await localChange(current=>{const pendingIds=new Set(current.queue.map(o=>o.order.id));state.orders.forEach(o=>{if(!current.orders.some(x=>x.id===o.id)&&!pendingIds.has(o.id))current.orders.push(o)});state.queue.forEach(o=>{if(!current.queue.some(x=>x.operationId===o.operationId)&&!pendingIds.has(o.order.id))current.queue.push(o)});Object.entries(state.counters||{}).forEach(([day,n])=>{if(Number.isSafeInteger(n))current.counters[day]=Math.max(current.counters[day]||0,n)})});await refreshLocal();showSnackbar('備份已合併，請確認待同步資料')}catch(e){showSnackbar(e.message)}finally{event.target.value=''}}
function exportCsv(){const rows=[['日期','類型','金額'],...orders.value.map(o=>[o.date,'營收',o.total])];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(value=>{let text=String(value);if(/^[=+@\-\t\r\n]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'}).join(',')).join('\n')],{type:'text/csv'}));a.download='accounts.csv';a.click();URL.revokeObjectURL(a.href)}
</script>
<template>
<dialog ref="deleteDialog" class="table-dialog price-dialog"><h2>刪除訂單</h2><p>將永久刪除整列訂單，無法復原。</p><p>{{deleteTarget?.id}}</p><button :disabled="busy" @click="deleteDialog.close()">取消</button><button class="primary" :disabled="busy" @click="confirmDelete">確認刪除</button></dialog>
<dialog ref="editDialog" class="table-dialog" aria-labelledby="edit-title"><form v-if="editOrder" @submit.prevent="saveOrder"><h2 id="edit-title">編輯訂單</h2><select v-model="editOrder.kind"><option>內用</option><option>外帶</option></select><select v-if="editOrder.kind==='內用'" v-model="editOrder.table"><option v-for="t in tableChoices.slice(1)">{{t}}</option></select><input v-model="editOrder.note" placeholder="整單備註"><article v-for="(i,n) in editOrder.items" class="panel"><strong>{{i.name}}</strong><select v-if="variants(i).length" v-model="i.variant"><option v-for="v in variants(i)" :value="v.value">{{v.label}}</option></select><label>數量<input type="number" min="1" step="1" v-model.number="i.qty"></label><label>單價<input type="number" :min="i.group==='減項'?-10000000:0" :max="i.group==='減項'?0:10000000" step="1" v-model.number="i.price"></label><select v-if="isDrink(i)" v-model="i.sweetness"><option v-for="v in levels">{{v}}</option></select><select v-if="i.variant.startsWith('冰')" v-model="i.ice"><option v-for="v in levels">{{v}}</option></select><select v-if="i.variant.startsWith('熱')" v-model="i.heat"><option>熱</option><option>溫</option></select><button type="button" @click="editOrder.items.splice(n,1)">移除品項</button></article><select @change="event=>{const p=menu.find(p=>p.id===event.target.value);if(p){const v=variants(p)[0];editOrder.items.push({...p,lineId:crypto.randomUUID(),qty:1,variant:v?.value||'',price:v?.price??p.price,sweetness:'正常',ice:'正常',heat:'熱'})}event.target.value=''}"><option value="">加入品項</option><option v-for="p in menu" :value="p.id">{{p.name}}</option></select><p role="alert">{{editError}}</p><button type="button" @click="editDialog.close()">取消</button><button class="primary" :disabled="busy">儲存</button></form></dialog>
<dialog ref="connectDialog" class="table-dialog price-dialog" aria-labelledby="connect-title"><form @submit.prevent="connect"><h2 id="connect-title">連線帳務</h2><label for="access-key">存取密碼</label><input id="access-key" autofocus v-model="keyInput" type="password" autocomplete="off" required><p class="price-error" role="alert">{{connectError}}</p><p>密碼會記住於這台裝置；中斷連線可移除此裝置保存的密碼。</p><div class="row"><button type="button" :disabled="connecting" @click="keyInput='';connectDialog.close()">取消</button><button class="primary" :disabled="connecting">{{connecting?'連線中…':'連線'}}</button></div></form></dialog>
<Teleport to="body"><div v-if="snackbar" class="snackbar" role="status" aria-live="polite">{{snackbar}}</div></Teleport>
<dialog ref="priceDialog" class="table-dialog price-dialog" aria-labelledby="price-dialog-title" @click="event=>{if(event.target===priceDialog)priceDialog.close()}"><form @submit.prevent="savePrice"><div class="dialog-heading"><h2 id="price-dialog-title">修改單價</h2></div><p>{{priceTarget?.name}} · 數量 {{priceTarget?.qty}}</p><label for="unit-price">單價（元）</label><input id="unit-price" autofocus v-model="priceValue"  :inputmode="priceTarget?.group==='減項'?'text':'numeric'" autocomplete="off" :aria-invalid="!!priceError" aria-describedby="price-error"><p id="price-error" class="price-error" role="alert">{{priceError}}</p><div class="row"><button type="button" @click="priceDialog.close()">取消</button><button class="primary" type="submit">確認修改</button></div></form></dialog>
<dialog ref="tableDialog" class="table-dialog" aria-labelledby="table-dialog-title" @click="event=>{if(event.target===tableDialog)tableDialog.close()}"><div class="dialog-heading"><h2 id="table-dialog-title">選擇桌號</h2><button autofocus aria-label="關閉桌號選擇" @click="tableDialog.close()">關閉</button></div><div class="table-grid"><button v-for="choice in tableChoices" :key="choice" :class="{selected:choice==='外帶'?kind==='外帶':kind==='內用'&&table===choice}" :aria-pressed="choice==='外帶'?kind==='外帶':kind==='內用'&&table===choice" @click="chooseTable(choice)">{{choice}}</button></div></dialog><div class="shell"><aside><nav><NuxtLink to="/"><UiIcon name="menu"/>點餐</NuxtLink><NuxtLink to="/orders"><UiIcon name="orders"/>訂單</NuxtLink><NuxtLink to="/accounts"><UiIcon name="chart"/>營收總覽</NuxtLink><NuxtLink to="/settings"><UiIcon name="settings"/>菜單設定</NuxtLink><button class="connection-button" :disabled="busy||connecting" @click="connected?disconnect():connectDialog.showModal()"><UiIcon name="link"/>{{connected?'中斷連線':'連線帳務'}}</button></nav><div class="connection-status" role="status"><span>{{online?'● 網路可用':'● 離線'}}</span><span>待備份 {{pendingCount}} 筆</span><small>{{lastSync?'上次備份 ' + new Date(lastSync).toLocaleString('zh-TW'):'尚未備份'}}</small><button class="sidebar-backup" :disabled="busy||!online||!connected" @click="sync"><UiIcon name="refresh"/>{{busy?'備份中…':'立即備份'}}</button><div class="storage-indicator"><span>本機儲存</span><strong>{{storageUsage}}</strong></div></div></aside><main><div v-if="message" class="notice" @click="message=''">{{message}} ×</div>
<div v-if="route.path==='/'" class="workspace"><section class="menu-column"><div class="categories"><button v-for="g in groups" :key="g[0]" :data-category="g[0]" :class="{active:category===g[0]}" @click="jump(g[0])">{{g[0]}}</button></div><div ref="menuScroll" class="menu-scroll" @wheel.passive="stopMenuAnimation" @touchstart.passive="stopMenuAnimation" @scroll.passive="track"><section v-for="g in groups" :key="g[0]" :data-group="g[0]" class="menu-group"><h2>{{g[0]}}</h2><div class="products"><div v-for="p in menu.filter(p=>p.group===g[0]&&p.active!==false)" :key="p.id" class="product"><div class="product-heading"><strong>{{p.name}}</strong><span class="menu-price">{{menuPrice(p)}}</span></div><div v-if="variants(p).length" class="menu-choices"><button v-for="option in variants(p)" :key="option.value" :class="option.value.startsWith('冰')?'cold':'hot'" :disabled="!writable" @click="add(p,option)">{{option.label}}</button></div><button v-else class="add-food" :disabled="!writable" @click="add(p)">加入</button></div></div></section></div></section><section class="ticket"><h2>本次訂單</h2><input :disabled="!writable" class="order-note" v-model="orderNote" aria-label="整張訂單備註" placeholder="整張訂單備註"><button class="table-picker" :disabled="!writable" @click="tableDialog.showModal()">{{kind==='外帶'?'外帶':'內用・'+table+' 桌'}} <span>選擇桌號</span></button><p v-if="pendingCheckout" class="pending-note">此單待確認，請連線後重試結單。</p><div class="cart" :inert="!writable"><p v-if="!cart.length" class="empty">尚未加入品項</p><article v-for="(i,index) in cart" :key="i.lineId||index" class="compact-item"><div class="item-heading"><strong><span class="item-bullet">{{index+1}}.</span>{{i.name}} <button v-if="i.variant && variants(i).length>1" class="temperature-badge temperature-toggle" :class="i.variant.startsWith('冰')?'cold':'hot'" :disabled="!writable" :aria-label="i.name+'：目前'+(i.variant.startsWith('冰')?'冰':'熱')+'，點擊切換冷熱'" @click="toggleTemperature(i)">{{i.variant.startsWith('冰')?'冰':(i.heat||'熱')}} ⇄</button><span v-else-if="i.variant" class="temperature-badge" :class="i.variant.startsWith('冰')?'cold':'hot'">{{i.variant.startsWith('冰')?'冰':(i.heat||'熱')}}</span></strong><button class="delete-item"  :aria-label="'刪除'+i.name" @click="cart.splice(index,1)">刪除</button></div><div class="item-customizations"><div v-if="isDrink(i)" class="option-row"><span>甜度</span><div class="option-tabs" role="group" :aria-label="i.name+'甜度'"><button v-for="v in levels" :key="v" :aria-pressed="i.sweetness===v" :class="{selected:i.sweetness===v}" @click="i.sweetness=v">{{v}}</button></div></div><div v-if="i.variant.startsWith('冰')" class="option-row"><span>冰量</span><div class="option-tabs" role="group" :aria-label="i.name+'冰量'"><button v-for="v in levels" :key="v" :aria-pressed="i.ice===v" :class="{selected:i.ice===v}" @click="i.ice=v">{{v}}</button></div></div><div v-if="i.variant.startsWith('熱')" class="option-row"><span>溫度</span><div class="option-tabs" role="group" :aria-label="i.name+'溫度'"><button v-for="v in ['熱','溫']" :key="v" :aria-pressed="i.heat===v" :class="{selected:i.heat===v}" @click="i.heat=v">{{v}}</button></div></div></div><div class="quantity-line"><button class="amount editable-price" :disabled="!writable" :aria-label="'修改'+i.name+'單價，目前'+money(i.price)" title="點擊修改單價" @click="editPrice(i)">{{money(i.qty*i.price)}}<small v-if="i.qty>1">{{money(i.price)}}／份</small></button><div class="quantity-controls"><button :disabled="i.qty<=1" aria-label="減少數量" @click="i.qty=Math.max(1,i.qty-1)">−</button><span>{{i.qty}}</span><button aria-label="增加數量" @click="i.qty++">＋</button></div></div></article></div><div class="checkout-bar"><div class="total" aria-label="總金額"><strong>{{money(total)}}</strong></div><button class="primary" :disabled="saving||!cart.length" @click="checkout">確認結單 →</button></div></section></div>
<section class="page-scroll dashboard" v-else-if="route.path==='/orders'"><header class="dashboard-header"><div><h1>訂單</h1><p>檢視每一筆訂單與餐點明細</p></div><div class="dashboard-tools"><button @click="shiftDay(-1)" aria-label="前一天">‹</button><DatePicker v-model="selectedMonth" v-model:day="selectedDay"/><button @click="shiftDay(1)" aria-label="後一天">›</button><button v-if="pendingCount" :disabled="busy" @click="renumberPending">重編待同步號碼</button></div></header><div v-if="false" class="dashboard-empty"><UiIcon name="link"/><h2>連線後查看訂單</h2><p>輸入存取密碼，讀取每月訂單紀錄。</p><button class="primary" @click="connectDialog.showModal()">連線帳務</button></div><template v-else><p class="chart-note">待同步 {{pendingCount}} 筆 · {{lastSync ? '最後同步：'+new Date(lastSync).toLocaleString('zh-TW') : '尚未同步'}}<span v-if="!monthComplete"> · 此月份尚未完整下載</span></p><div class="mini-summary"><span>當日營收 <b>{{money(dailyTotal)}}</b></span><span>本月營收 <b>{{money(net)}}</b></span></div><p v-if="!filteredOrders.length" class="dashboard-empty">這一天尚無訂單</p><div class="order-grid"><article v-for="o in filteredOrders" :key="o.id" class="order-card"><div class="order-card-top"><span class="order-number">{{orderLabel(o)}}</span><span class="sync-tag">{{pendingIds.has(o.id)?'待同步':'已同步'}}</span><span class="order-type" :class="{takeaway:o.kind==='外帶'}">{{o.kind}}</span><span v-if="!o.items.length" class="refund-tag">已全退</span></div><div class="order-card-main"><h2>{{o.kind==='外帶'?'外帶':o.table+' 桌'}}</h2><strong>{{money(o.total)}}</strong></div><div class="order-card-meta"><span><UiIcon name="bag"/>{{itemCount(o)}} 件餐點</span><span><UiIcon name="clock"/>{{dateLabel(o.date)}} · {{timeLabel(o.date)}}</span></div><button class="expand-order" :aria-expanded="expandedOrders.has(o.id)" :aria-controls="'detail-'+o.id" @click="toggleOrder(o.id)">{{expandedOrders.has(o.id)?'收合明細':'查看明細'}}<UiIcon name="chevron" :class="{rotated:expandedOrders.has(o.id)}"/></button><div v-if="expandedOrders.has(o.id)" :id="'detail-'+o.id" class="order-details"><div v-for="(i,index) in o.items" :key="i.lineId" class="detail-item"><div><strong>{{index+1}}. {{i.name}}</strong><p>{{[i.variant,i.sweetness?'甜度 '+i.sweetness:'',i.ice?'冰量 '+i.ice:'',i.heat].filter(Boolean).join(' · ')}}</p><small>{{money(i.price)}} × {{i.qty}}</small></div><div><strong>{{money(i.price*i.qty)}}</strong><button :disabled="busy" @click="refund(o,i)">退單</button></div></div><p v-if="o.note" class="order-note-display">備註：{{o.note}}</p><p v-if="o.refundReason" class="order-note-display">最後退單：{{o.refundReason}}</p><p class="uuid-text">UUID：{{o.id}}</p><div class="order-actions"><button :disabled="busy" @click="openOrder(o)">編輯訂單</button><button class="danger-button" :disabled="busy" @click="deleteOrder(o)">刪除訂單</button></div></div></article></div></template></section>
<section class="page-scroll dashboard" v-else-if="route.path==='/accounts'"><header class="dashboard-header"><h1>營收總覽</h1><div class="dashboard-tools"><button @click="shiftMonth(-1)" aria-label="上個月">‹</button><MonthPicker v-model="selectedMonth"/><button @click="shiftMonth(1)" aria-label="下個月">›</button></div></header><p class="chart-note">本機資料 · 待同步 {{pendingCount}} 筆變更 · {{monthComplete?'月份資料完整':'月份資料未完整下載'}}</p><div class="metric-grid"><article class="metric-card featured"><p>本月營收</p><strong>{{money(net)}}</strong></article><article class="metric-card"><p>本月訂單數量</p><strong>{{orders.length}} 筆</strong></article></div><article class="dashboard-panel"><h2>每日營收（元）</h2><div class="line-chart"><svg viewBox="0 0 800 245" role="img" :aria-label="selectedMonth+' 每日營收折線圖'"><line x1="40" y1="215" x2="760" y2="215" stroke="#d9dfd1"/><line x1="40" y1="40" x2="760" y2="40" stroke="#edf1e5"/><path :d="chartPath" fill="none" stroke="#65452f" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><g v-for="(point,index) in chartPoints" :key="point.date"><circle :cx="point.x" :cy="point.y" r="5" fill="#65452f"><title>{{point.date}}：{{money(point.total)}}</title></circle><text v-if="index%5===0||index===chartPoints.length-1" :x="point.x" y="240" text-anchor="middle" font-size="11" fill="#705748">{{point.date.slice(8)}}</text></g></svg><p>橫軸為日期，縱軸為營收（元）；點選資料點可查看金額。</p></div></article></section>
<section v-else-if="route.path==='/settings'" class="page-scroll settings-page"><div class="settings-wrap"><header class="settings-header"><div><span class="settings-eyebrow">CAFÉ POS · MENU</span><h1>菜單設定</h1><p>先建立分類，再為分類加入品項與價格。</p></div><button v-if="adminUnlocked" class="quiet-button" @click="adminUnlocked=false">鎖定後台</button></header><form v-if="!adminUnlocked" class="settings-lock" @submit.prevent="unlockAdmin"><div class="settings-lock-mark">✦</div><h2>管理菜單</h2><p>輸入管理 PIN，首次使用請設定至少六位數。</p><label>管理 PIN<input v-model="adminInput" type="password" inputmode="numeric" autocomplete="off" placeholder="請輸入 PIN"></label><p class="field-error" role="alert">{{adminError}}</p><button class="primary">進入後台 →</button></form><template v-else><div class="settings-grid"><section class="settings-categories"><div class="settings-pane-head"><div><span>01 / 分類</span><h2>菜單分類</h2></div><button class="icon-action" aria-label="新增分類" @click="openCategoryDialog()">＋</button></div><p class="settings-hint">選取分類後，在右側編輯品項。</p><div class="settings-category-list"><div v-for="(group,index) in groups" :key="group[0]" class="settings-category-row" :class="{selected:selectedSettingsCategory===group[0]}"><button class="category-select" @click="selectedSettingsCategory=group[0]"><span>{{group[0]}}</span><small>{{menu.filter(item=>item.group===group[0]).length}} 項</small></button><button class="category-edit" :aria-label="'編輯'+group[0]" @click="openCategoryDialog(group)">⋯</button></div></div><button class="settings-add-category" @click="openCategoryDialog()">＋ 新增分類</button><div class="settings-storage"><button :disabled="!connected" @click="menuRestoreDialog.showModal()">從雲端還原菜單</button></div></section><div class="settings-items"><div class="settings-pane-head"><div><span>02 / 品項</span><h2>{{selectedSettingsCategory||'請先選擇分類'}}</h2><p>{{visibleSettingsItems.length}} 個品項 · 本機修改會定時備份</p></div><button class="primary" :disabled="!selectedSettingsCategory" @click="openItemDialog()">＋ 新增品項</button></div><div v-if="!visibleSettingsItems.length" class="settings-empty"><strong>這個分類還沒有品項</strong><p>按「新增品項」開始建立菜單。</p></div><div class="settings-item-list"><article v-for="(item,index) in visibleSettingsItems" :key="item.id" class="settings-item-card" :class="{inactive:item.active===false}"><div class="settings-item-main"><span class="settings-item-index">{{String(index+1).padStart(2,'0')}}</span><div><h3>{{item.name}}</h3><p>{{itemMode({options:menuOptions(item)})}} · {{item.active===false?'已停用':'販售中'}}</p></div></div><strong>{{menuPrice(item)}}</strong><div class="settings-item-actions"><button :aria-label="item.name+'上移'" @click="moveItem(item,-1)">↑</button><button :aria-label="item.name+'下移'" @click="moveItem(item,1)">↓</button><button @click="openItemDialog(item)">編輯</button></div></article></div></div></div></template></div><dialog ref="categoryDialog" class="settings-dialog" @click="event=>{if(event.target===categoryDialog)categoryDialog.close()}"><form @submit.prevent="saveCategory"><span class="settings-eyebrow">MENU CATEGORY</span><h2>{{editingCategory?'編輯分類':'新增分類'}}</h2><label>分類名稱<input v-model="categoryDraft" maxlength="100" placeholder="例如：手沖咖啡" autofocus></label><p class="field-error" role="alert">{{categoryError}}</p><div class="settings-dialog-actions"><button type="button" @click="categoryDialog.close()">取消</button><button class="primary">儲存分類</button></div><button v-if="editingCategory&&editingCategory[0]!=='減項'" type="button" class="text-danger" @click="removeCategory(editingCategory)">移除分類</button></form></dialog><dialog ref="itemDialog" class="settings-dialog item-editor-dialog" @click="event=>{if(event.target===itemDialog)itemDialog.close()}"><form v-if="itemDraft" @submit.prevent="saveItemDraft"><span class="settings-eyebrow">MENU ITEM</span><h2>{{editingItemId?'編輯品項':'新增品項'}}</h2><div class="settings-form-grid"><label class="settings-item-name">品項名稱<input v-model="itemDraft.name" type="text" maxlength="200" placeholder="例如：拿鐵" autofocus></label><div ref="itemCategoryPicker" class="settings-category-field"><span id="item-category-label">分類</span><button type="button" class="settings-category-trigger" aria-labelledby="item-category-label" :aria-expanded="itemCategoryOpen" aria-controls="item-category-options" @click="itemCategoryOpen=!itemCategoryOpen"><span>{{itemDraft.group||'請選擇分類'}}</span><span class="settings-category-chevron" :class="{open:itemCategoryOpen}" aria-hidden="true">⌄</span></button><div v-if="itemCategoryOpen" id="item-category-options" class="settings-category-menu"><button v-for="group in groups" :key="group[2]||group[0]" type="button" :class="{selected:itemDraft.group===group[0]}" @click="chooseItemCategory(group[0])"><span>{{group[0]}}</span><span v-if="itemDraft.group===group[0]" aria-hidden="true">✓</span></button></div></div></div><label v-if="itemDraft.group!=='減項'">冷熱選項</label><div v-if="itemDraft.group!=='減項'" class="settings-segments" role="group" aria-label="冷熱選項"><button v-for="mode in ['無冷熱','僅冰','僅熱','冰熱都有']" :key="mode" type="button" :class="{selected:itemMode(itemDraft)===mode}" @click="setItemMode(mode)">{{mode}}</button></div><div v-if="!itemDraft.options.length" class="settings-price-field"><label>{{itemDraft.group==='減項'?'減項單價（元）':'單價（元）'}}<input v-model.number="itemDraft.price" type="number" :min="itemDraft.group==='減項'?-10000000:0" :max="itemDraft.group==='減項'?0:10000000" step="1" inputmode="numeric"></label></div><div v-else class="settings-price-grid"><label v-for="option in itemDraft.options" :key="option.value">{{option.value.startsWith('冰')?'冰':'熱'}}價（元）<input v-model.number="option.price" type="number" min="0" step="1" inputmode="numeric"></label></div><label class="settings-toggle"><input v-model="itemDraft.active" type="checkbox"><span>啟用此品項</span></label><p class="field-error" role="alert">{{itemError}}</p><div class="settings-dialog-actions"><button type="button" @click="itemDialog.close()">取消</button><button class="primary">儲存品項</button></div></form></dialog><dialog ref="menuRestoreDialog" class="settings-dialog" @click="event=>{if(event.target===menuRestoreDialog)menuRestoreDialog.close()}"><h2>從雲端還原菜單</h2><p>這會覆蓋此裝置目前的菜單設定。</p><div class="settings-dialog-actions"><button @click="menuRestoreDialog.close()">取消</button><button class="primary" @click="restoreMenuFromCloud">確認還原</button></div></dialog></section>
<section v-else class="page-scroll"><p>找不到此頁面</p><NuxtLink to="/">返回點餐</NuxtLink></section></main></div>
</template>
